import itertools

def solve():
    n = 4
    edges = list(itertools.combinations(range(n), 2))
    T = len(edges)
    min_cost = float('inf')

    for p in itertools.permutations(range(1, T + 1)):
        # p is the labeling of the edges
        # edges[i] is the pair of vertices, p[i] is its label
        labels = {}
        for i in range(T):
            labels[edges[i]] = p[i]

        cost = 0
        for i in range(n):
            # find all labels incident to vertex i
            D_i = []
            for edge in edges:
                if i in edge:
                    D_i.append(labels[edge])
            cost += max(D_i) - min(D_i) + 1

        if cost < min_cost:
            min_cost = cost
    return min_cost

print(solve())

