def solve():
    n = 4
    edges = list(itertools.combinations(range(n), 2))
    T = len(edges)
    min_cost = float('inf')
    best_labels = None

    for p in itertools.permutations(range(1, T + 1)):
        labels = {}
        for i in range(T):
            labels[edges[i]] = p[i]

        cost = 0
        for i in range(n):
            D_i = []
            for edge in edges:
                if i in edge:
                    D_i.append(labels[edge])
            cost += max(D_i) - min(D_i) + 1

        if cost < min_cost:
            min_cost = cost
            best_labels = p

    # Now find a_t and b_t for the best_labels
    labels = {}
    for i in range(T):
        labels[edges[i]] = best_labels[i]

    a = []
    for t in range(1, T + 1):
        # a_t is the number of players who have played a match by day t
        # i.e., i such that f_i <= t
        # f_i is the minimum label of an edge incident to vertex i
        count = 0
        for i in range(n):
            D_i = []
            for edge in edges:
                if i in edge:
                    D_i.append(labels[edge])
            if min(D_i) <= t:
                count += 1
        a.append(count)

    b = []
    for t in range(1, T + 1):
        # b_t is the number of players who will play a match on or after day t
        # i.e., i such that l_i >= t
        # l_i is the maximum label of an edge incident to vertex i
        count = 0
        for i in range(n):
            D_i = []
            for edge in edges:
                if i in edge:
                    D_i.append(labels[edge])
            if max(D_i) >= t:
                count += 1
        b.append(count)

    print(f"min_cost: {min_cost}")
    print(f"a: {a}")
    print(f"b: {b}")
    print(f"sum(a): {sum(a)}")
    print(f"sum(b): {sum(b)}")
    print(f"sum(a) + sum(b) - n*T: {sum(a) + sum(b) - n*T}")

solve()

